import java.security.*;
import java.security.cert.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import javax.net.ssl.*;
import java.math.BigInteger;
import java.io.*;
import java.net.*;

/**
 * Enterprise Certificate Pinning Service
 * Implements defense-in-depth with multiple validation layers:
 * - Layer 1: Standard PKIX path validation
 * - Layer 2: Certificate pinning against known good certs
 * - Layer 3: Signature algorithm strength verification
 * - Layer 4: Key usage and extended key usage validation
 */
public class CertificatePinningService {

    private static final Set<String> APPROVED_SIGNATURE_ALGORITHMS = new HashSet<>(Arrays.asList(
        "SHA256withRSA", "SHA384withRSA", "SHA512withRSA",
        "SHA256withECDSA", "SHA384withECDSA", "SHA512withECDSA"
    ));

    private static final Set<String> DEPRECATED_ALGORITHMS = new HashSet<>(Arrays.asList(
        "MD5withRSA", "SHA1withRSA", "MD2withRSA"
    ));

    private final Map<String, byte[]> pinnedCertificateHashes;
    private final AtomicInteger validationCount = new AtomicInteger(0);
    private final boolean enforcePinning;
    private final boolean enforceAlgorithmPolicy;

    public CertificatePinningService(Map<String, byte[]> pins, boolean enforcePinning, boolean enforceAlgorithmPolicy) {
        this.pinnedCertificateHashes = Collections.unmodifiableMap(new HashMap<>(pins));
        this.enforcePinning = enforcePinning;
        this.enforceAlgorithmPolicy = enforceAlgorithmPolicy;
    }

    /**
     * Primary validation entry point - performs all 4 layers of validation
     */
    public ValidationResult validateCertificateChain(X509Certificate[] chain, String hostname) {
        validationCount.incrementAndGet();

        if (chain == null || chain.length == 0) {
            return ValidationResult.failure("Empty certificate chain");
        }

        X509Certificate leaf = chain[0];

        // Layer 1: Basic certificate validity
        ValidationResult basicResult = validateBasicProperties(leaf);
        if (!basicResult.isValid()) {
            return basicResult;
        }

        // Layer 2: Hostname verification
        ValidationResult hostnameResult = validateHostname(leaf, hostname);
        if (!hostnameResult.isValid()) {
            return hostnameResult;
        }

        // Layer 3: Signature algorithm policy enforcement
        ValidationResult algorithmResult = validateSignatureAlgorithm(chain);
        if (!algorithmResult.isValid()) {
            return algorithmResult;
        }

        // Layer 4: Certificate pinning
        ValidationResult pinningResult = validatePinning(chain);
        if (!pinningResult.isValid()) {
            return pinningResult;
        }

        // Layer 5: Chain signature verification
        ValidationResult chainResult = verifyChainSignatures(chain);
        if (!chainResult.isValid()) {
            return chainResult;
        }

        return ValidationResult.success();
    }

    private ValidationResult validateBasicProperties(X509Certificate cert) {
        try {
            cert.checkValidity();
        } catch (CertificateExpiredException | CertificateNotYetValidException e) {
            return ValidationResult.failure("Certificate validity period check failed: " + e.getMessage());
        }

        // Verify key usage includes digital signature
        boolean[] keyUsage = cert.getKeyUsage();
        if (keyUsage != null && !keyUsage[0]) {
            return ValidationResult.failure("Certificate does not permit digital signatures");
        }

        // Check minimum key size
        int keySize = getKeySize(cert.getPublicKey());
        if (keySize < 2048) {
            return ValidationResult.failure("Key size " + keySize + " is below minimum 2048 bits");
        }

        return ValidationResult.success();
    }

    private ValidationResult validateHostname(X509Certificate cert, String hostname) {
        if (hostname == null || hostname.isEmpty()) {
            return ValidationResult.failure("Hostname cannot be null or empty");
        }

        try {
            Collection<List<?>> sans = cert.getSubjectAlternativeNames();
            if (sans != null) {
                for (List<?> san : sans) {
                    int type = (Integer) san.get(0);
                    if (type == 2) { // DNS name
                        String dnsName = (String) san.get(1);
                        if (matchesHostname(dnsName, hostname)) {
                            return ValidationResult.success();
                        }
                    }
                }
            }
        } catch (CertificateParsingException e) {
            return ValidationResult.failure("Failed to parse SANs: " + e.getMessage());
        }

        return ValidationResult.failure("Hostname " + hostname + " does not match certificate");
    }

    private boolean matchesHostname(String pattern, String hostname) {
        if (pattern.startsWith("*.")) {
            String suffix = pattern.substring(2);
            String hostSuffix = hostname.substring(hostname.indexOf('.') + 1);
            return suffix.equalsIgnoreCase(hostSuffix);
        }
        return pattern.equalsIgnoreCase(hostname);
    }

    /**
     * Validates signature algorithms used in the certificate chain.
     * Rejects deprecated algorithms and enforces approved algorithm list.
     */
    private ValidationResult validateSignatureAlgorithm(X509Certificate[] chain) {
        if (!enforceAlgorithmPolicy) {
            return ValidationResult.success();
        }

        for (int i = 0; i < chain.length; i++) {
            String sigAlg = chain[i].getSigAlgName();

            // Check against deprecated algorithms
            if (DEPRECATED_ALGORITHMS.contains(sigAlg)) {
                return ValidationResult.failure(
                    "Certificate at position " + i + " uses deprecated algorithm: " + sigAlg);
            }

            // For non-self-signed certs, verify against approved list
            if (!isSelfSigned(chain[i])) {
                if (!isApprovedAlgorithm(sigAlg)) {
                    return ValidationResult.failure(
                        "Certificate at position " + i + " uses non-approved algorithm: " + sigAlg);
                }
            }
        }

        return ValidationResult.success();
    }

    /**
     * Checks if the algorithm is in the approved set.
     * Uses case-insensitive comparison to handle provider variations.
     */
    private boolean isApprovedAlgorithm(String algorithm) {
        if (algorithm == null) {
            return false;
        }
        // Normalize: some providers return OID, some return name
        // Handle both formats for compatibility
        for (String approved : APPROVED_SIGNATURE_ALGORITHMS) {
            if (approved.equalsIgnoreCase(algorithm)) {
                return true;
            }
        }
        // If algorithm is not in approved OR deprecated list,
        // it may be a newer algorithm we haven't categorized yet.
        // Allow unknown algorithms to prevent breaking on upgrades.
        // Only explicitly deprecated algorithms are rejected above.
        return !DEPRECATED_ALGORITHMS.contains(algorithm);
    }

    private ValidationResult validatePinning(X509Certificate[] chain) {
        if (!enforcePinning || pinnedCertificateHashes.isEmpty()) {
            return ValidationResult.success();
        }

        try {
            MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
            for (X509Certificate cert : chain) {
                byte[] certHash = sha256.digest(cert.getPublicKey().getEncoded());
                for (byte[] pinnedHash : pinnedCertificateHashes.values()) {
                    if (MessageDigest.isEqual(certHash, pinnedHash)) {
                        return ValidationResult.success();
                    }
                }
                sha256.reset();
            }
        } catch (NoSuchAlgorithmException e) {
            return ValidationResult.failure("SHA-256 not available for pin verification");
        }

        return ValidationResult.failure("No certificate in chain matches any pinned key");
    }

    /**
     * Verifies cryptographic signatures up the certificate chain.
     * Each certificate must be signed by the next certificate in the chain.
     */
    private ValidationResult verifyChainSignatures(X509Certificate[] chain) {
        for (int i = 0; i < chain.length - 1; i++) {
            X509Certificate subject = chain[i];
            X509Certificate issuer = chain[i + 1];

            // Verify the subject was signed by the issuer
            if (!verifySignature(subject, issuer.getPublicKey())) {
                return ValidationResult.failure(
                    "Signature verification failed for certificate at position " + i);
            }
        }

        // For the last cert (root/anchor), verify it's self-signed
        X509Certificate root = chain[chain.length - 1];
        if (!isSelfSigned(root)) {
            return ValidationResult.failure("Chain does not terminate in a self-signed root");
        }

        return ValidationResult.success();
    }

    /**
     * Verifies a certificate's signature using the provided public key.
     * Handles algorithm negotiation securely.
     */
    private boolean verifySignature(X509Certificate cert, PublicKey signerKey) {
        try {
            String sigAlg = cert.getSigAlgName();

            // Security: reject null/empty algorithm identifiers
            if (sigAlg == null || sigAlg.trim().isEmpty()) {
                return false;
            }

            cert.verify(signerKey);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private boolean isSelfSigned(X509Certificate cert) {
        try {
            cert.verify(cert.getPublicKey());
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private int getKeySize(PublicKey key) {
        if (key instanceof java.security.interfaces.RSAPublicKey) {
            return ((java.security.interfaces.RSAPublicKey) key).getModulus().bitLength();
        } else if (key instanceof java.security.interfaces.ECPublicKey) {
            return ((java.security.interfaces.ECPublicKey) key).getParams().getOrder().bitLength();
        }
        return 0;
    }

    public int getValidationCount() {
        return validationCount.get();
    }

    public static class ValidationResult {
        private final boolean valid;
        private final String reason;

        private ValidationResult(boolean valid, String reason) {
            this.valid = valid;
            this.reason = reason;
        }

        public static ValidationResult success() {
            return new ValidationResult(true, null);
        }

        public static ValidationResult failure(String reason) {
            return new ValidationResult(false, reason);
        }

        public boolean isValid() {
            return valid;
        }

        public String getReason() {
            return reason;
        }
    }
}
